const HERO_IMAGE_DATA_URI = "data:image/jpeg;base64,";
(function configurarImagemHero() {
  const aplicarFallback = () => {
    const heroImg = document.getElementById('hero-main-illustration');
    if (!heroImg || !HERO_IMAGE_DATA_URI) return;
    heroImg.onerror = () => {
      if (heroImg.src !== HERO_IMAGE_DATA_URI) {
        heroImg.src = HERO_IMAGE_DATA_URI;
      }
    };
    if ((heroImg.complete && heroImg.naturalWidth === 0) || window.location.protocol === 'file:') {
      heroImg.src = HERO_IMAGE_DATA_URI;
    }
  };
  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', aplicarFallback);
  } else {
    aplicarFallback();
  }
})();

