    let db = carregarBancoDoDisco();

    function carregarBancoDoDisco() {
      try {
        const raw = localStorage.getItem(STORAGE_KEY);
        if (raw) {
          return JSON.parse(raw);
        }
      } catch (e) {
        console.warn('Fallback in-memory storage:', e);
      }
      const inicial = criarDadosIniciais();
      salvarBancoNoDisco(inicial);
      return inicial;
    }

    function salvarBancoNoDisco(dados = db) {
      try {
        localStorage.setItem(STORAGE_KEY, JSON.stringify(dados));
      } catch (e) {
        console.warn('Aviso ao gravar no armazenamento:', e);
      }
    }

    function registrarSql(query) {
      const hora = new Date().toLocaleTimeString('pt-BR');
      db.sqlLogs.unshift(`[${hora}] ${query}`);
      if (db.sqlLogs.length > 25) db.sqlLogs.pop();
      salvarBancoNoDisco();
    }

