    function mostrarToast(titulo, mensagem, tipo = 'sucesso') {
      const container = document.getElementById('toast-container');
      const cores = {
        sucesso: 'bg-slate-900 border-teal-500 text-white',
        info: 'bg-blue-950 border-blue-400 text-white',
        alerta: 'bg-amber-950 border-amber-400 text-white'
      };
      const el = document.createElement('div');
      el.className = `pointer-events-auto p-4 rounded-xl border-l-4 shadow-xl transition-all duration-300 ${cores[tipo] || cores.sucesso}`;
      el.innerHTML = `
        <div class="flex items-start justify-between gap-2">
          <div>
            <p class="font-bold text-xs uppercase tracking-wider text-teal-400">${titulo}</p>
            <p class="text-xs text-slate-200 mt-0.5">${mensagem}</p>
          </div>
          <span class="text-[10px] font-semibold px-1.5 py-0.5 rounded bg-white/10">Salvo</span>
        </div>
      `;
      container.appendChild(el);
      setTimeout(() => {
        el.style.opacity = '0';
        setTimeout(() => el.remove(), 300);
      }, 3600);
    }

