    function obterNomeCliente(clienteId) {
      const c = db.clientes.find(item => item.id === Number(clienteId));
      return c ? c.nome : 'Paciente Removido';
    }

    function obterTelefoneCliente(clienteId) {
      const c = db.clientes.find(item => item.id === Number(clienteId));
      return c ? c.telefone : '-';
    }

    function formatarDataBR(isoDate) {
      if (!isoDate) return '-';
      const parts = isoDate.split('-');
      if (parts.length !== 3) return isoDate;
      return `${parts[2]}/${parts[1]}/${parts[0]}`;
    }

