    function renderizarPainelRetornos() {
      const tbody = document.getElementById('tabela-retornos-body');
      const hojeISO = '2026-10-22';

      let atrasados = 0;
      let agendados = 0;
      let concluidos = 0;

      db.procedimentos.forEach(p => {
        if (p.retornoConcluido) {
          concluidos++;
        } else if (p.dataRetorno < hojeISO) {
          atrasados++;
        } else {
          agendados++;
        }
      });

      document.getElementById('kpi-ret-atrasados').textContent = atrasados;
      document.getElementById('kpi-ret-agendados').textContent = agendados;
      document.getElementById('kpi-ret-concluidos').textContent = concluidos;

      const filtrados = db.procedimentos.filter(p => {
        if (currentRetornoFilter === 'PENDENTE') return !p.retornoConcluido;
        if (currentRetornoFilter === 'CONCLUIDO') return p.retornoConcluido;
        return true;
      });

      tbody.innerHTML = '';

      filtrados.forEach(p => {
        const tr = document.createElement('tr');
        tr.className = 'hover:bg-slate-50 transition';

        let badgeHtml = '';
        if (p.retornoConcluido) {
          badgeHtml = '<span class="px-2.5 py-1 rounded-full text-xs font-bold bg-emerald-100 text-emerald-800">✓ Compareceu</span>';
        } else if (p.dataRetorno < hojeISO) {
          badgeHtml = '<span class="px-2.5 py-1 rounded-full text-xs font-bold bg-rose-100 text-rose-800">⚠ Atrasado</span>';
        } else {
          badgeHtml = '<span class="px-2.5 py-1 rounded-full text-xs font-bold bg-amber-100 text-amber-800">⏳ Agendado</span>';
        }

        tr.innerHTML = `
          <td class="py-3 px-4">
            <p class="font-bold text-slate-900">${obterNomeCliente(p.clienteId)}</p>
            <p class="text-xs text-slate-500">${obterTelefoneCliente(p.clienteId)}</p>
          </td>
          <td class="py-3 px-4 font-medium text-slate-800">${p.tipo}</td>
          <td class="py-3 px-4 text-slate-600 text-xs">${formatarDataBR(p.dataProcedimento)}</td>
          <td class="py-3 px-4 font-semibold text-slate-900 text-xs">${formatarDataBR(p.dataRetorno)}</td>
          <td class="py-3 px-4">${badgeHtml}</td>
          <td class="py-3 px-4 text-right">
            <button type="button" data-toggle-retorno="${p.id}" class="px-3 py-1.5 rounded-lg text-xs font-semibold transition ${
              p.retornoConcluido
                ? 'bg-slate-200 hover:bg-slate-300 text-slate-700'
                : 'bg-teal-600 hover:bg-teal-700 text-white shadow-sm'
            }">
              ${p.retornoConcluido ? 'Reabrir Retorno' : 'Confirmar Presença'}
            </button>
          </td>
        `;
        tbody.appendChild(tr);
      });
    }

    function renderizarConsoleSqlite() {
      const logBox = document.getElementById('sql-log-console');
      const rawTbody = document.getElementById('sqlite-raw-tbody');
      const sizeSpan = document.getElementById('sqlite-byte-size');

      const serialized = JSON.stringify(db);
      const kb = (serialized.length / 1024).toFixed(1);
      sizeSpan.textContent = `${kb} KB gravados`;

      logBox.innerHTML = db.sqlLogs.map(line => `<div class="py-1 border-b border-slate-800/80">${line}</div>`).join('');

      rawTbody.innerHTML = '';
      db.procedimentos.forEach(p => {
        const tr = document.createElement('tr');
        tr.innerHTML = `
          <td class="p-2 font-bold text-teal-700">${p.id}</td>
          <td class="p-2">${p.clienteId} (${obterNomeCliente(p.clienteId).split(' ')[0]})</td>
          <td class="p-2">${p.tipo.slice(0, 22)}...</td>
          <td class="p-2">${p.dataProcedimento}</td>
          <td class="p-2">${p.dataRetorno}</td>
          <td class="p-2 text-purple-700">IMG (${Math.round((p.fotoBase64 || '').length / 1024)}KB)</td>
          <td class="p-2">${p.retornoConcluido ? '1 (SIM)' : '0 (NÃO)'}</td>
        `;
        rawTbody.appendChild(tr);
      });
    }

