      models: `// Models/AppDbContext.cs — Todas as entidades + contexto SQLite em 35 linhas
using Microsoft.EntityFrameworkCore;

namespace ClinicaMvc.Models;

public class Cliente {
    public int Id { get; set; }
    public string Nome { get; set; } = "";
    public string Telefone { get; set; } = "";
    public string Cpf { get; set; } = "";
}

public class Procedimento {
    public int Id { get; set; }
    public int ClienteId { get; set; }
    public Cliente? Cliente { get; set; }
    public string Tipo { get; set; } = "";
    public string DataProcedimento { get; set; } = "";
    public string DataRetorno { get; set; } = "";
    public string Observacoes { get; set; } = "";
    public string FotoBase64 { get; set; } = ""; // Salva a foto direto no SQLite!
    public bool RetornoConcluido { get; set; }
}

public class AppDbContext : DbContext {
    public DbSet<Cliente> Clientes => Set<Cliente>();
    public DbSet<Procedimento> Procedimentos => Set<Procedimento>();

    protected override void OnConfiguring(DbContextOptionsBuilder options)
        => options.UseSqlite("Data Source=clinica.db");
}`,

      controller: `// Controllers/ClinicaController.cs — 1 Único Controller para os 5 itens do escopo
using Microsoft.AspNetCore.Mvc;
using Microsoft.EntityFrameworkCore;
using ClinicaMvc.Models;

namespace ClinicaMvc.Controllers;

public class ClinicaController(AppDbContext db) : Controller {

    // 4 & 5. Listagem de Histórico + Painel de Retornos na mesma View principal
    public IActionResult Index() {
        ViewBag.Clientes = db.Clientes.ToList();
        var historico = db.Procedimentos.Include(p => p.Cliente)
                          .OrderByDescending(p => p.Id).ToList();
        return View(historico);
    }

    // 1. Criação de Cliente
    [HttpPost]
    public IActionResult CriarCliente(Cliente novo) {
        db.Clientes.Add(novo);
        db.SaveChanges();
        return RedirectToAction("Index");
    }

    // 2 & 3. Registro de Procedimento + Upload de Foto (salvo em Base64 no SQLite)
    [HttpPost]
    public async Task<IActionResult> RegistrarProcedimento(Procedimento proc, IFormFile? foto) {
        if (foto != null && foto.Length > 0) {
            using var ms = new MemoryStream();
            await foto.CopyToAsync(ms);
            proc.FotoBase64 = $"data:{foto.ContentType};base64,{Convert.ToBase64String(ms.ToArray())}";
        }
        db.Procedimentos.Add(proc);
        db.SaveChanges();
        return RedirectToAction("Index");
    }

    // 5. Marcar Retorno como Concluído no Painel
    [HttpPost]
    public IActionResult AlternarRetorno(int id) {
        var proc = db.Procedimentos.Find(id);
        if (proc != null) {
            proc.RetornoConcluido = !proc.RetornoConcluido;
            db.SaveChanges();
        }
        return RedirectToAction("Index");
    }
}`,

      program: `// Program.cs — Configuração enxuta com criação automática do banco SQLite
using ClinicaMvc.Models;

var builder = WebApplication.CreateBuilder(args);
builder.Services.AddControllersWithViews();
builder.Services.AddDbContext<AppDbContext>();

var app = builder.Build();

// Garante que o arquivo clinica.db e as tabelas existam sem precisar de Migrations!
using (var scope = app.Services.CreateScope()) {
    var db = scope.ServiceProvider.GetRequiredService<AppDbContext>();
    db.Database.EnsureCreated();
}

app.UseStaticFiles();
app.UseRouting();
app.MapControllerRoute(name: "default", pattern: "{controller=Clinica}/{action=Index}/{id?}");
app.Run();`
