    // =========================================================================
    // 5. EVENT LISTENERS E INTERATIVIDADE COMPLETA
    // =========================================================================
    function ativarAbaApp(tabId) {
      document.querySelectorAll('.app-tab-panel').forEach(panel => {
        panel.classList.toggle('hidden', panel.id !== tabId);
      });
      document.querySelectorAll('.app-tab-btn').forEach(btn => {
        const ativo = btn.getAttribute('data-tab') === tabId;
        btn.className = ativo
          ? 'app-tab-btn px-3 py-1.5 rounded-lg text-xs font-semibold bg-teal-500 text-white transition'
          : 'app-tab-btn px-3 py-1.5 rounded-lg text-xs font-semibold bg-slate-800 text-slate-300 hover:bg-slate-700 transition';
      });
    }

    window.addEventListener('DOMContentLoaded', () => {
      // Datas padrão nos inputs
      document.getElementById('input-proc-data').value = '2026-10-22';
      document.getElementById('input-proc-retorno').value = '2026-11-05';

      // Navegação de abas do sistema
      document.querySelectorAll('.app-tab-btn').forEach(btn => {
        btn.addEventListener('click', () => {
          ativarAbaApp(btn.getAttribute('data-tab'));
        });
      });

      // Cards do escopo que levam direto para a aba correspondente
      document.querySelectorAll('.scope-card').forEach(card => {
        card.addEventListener('click', () => {
          const targetTab = card.getAttribute('data-goto-tab');
          ativarAbaApp(targetTab);
          document.getElementById('sistema-interativo').scrollIntoView({ behavior: 'smooth' });
        });
      });

      // 1. Submissão de Novo Cliente
      document.getElementById('form-cliente').addEventListener('submit', (e) => {
        e.preventDefault();
        const nome = document.getElementById('input-cliente-nome').value.trim();
        const telefone = document.getElementById('input-cliente-tel').value.trim();
        const cpf = document.getElementById('input-cliente-cpf').value.trim() || 'Não informado';
        if (!nome || !telefone) return;

        const novoId = db.clientes.length > 0 ? Math.max(...db.clientes.map(c => c.id)) + 1 : 1;
        db.clientes.push({
          id: novoId,
          nome,
          telefone,
          cpf,
          criadoEm: '2026-10-22'
        });

        registrarSql(`INSERT INTO Clientes (Id, Nome, Telefone, Cpf) VALUES (${novoId}, '${nome}', '${telefone}', '${cpf}');`);
        renderizarTudo();
        document.getElementById('select-proc-cliente').value = String(novoId);
        e.target.reset();
        mostrarToast('Paciente Cadastrado', `${nome} foi adicionado à lista de clientes da clínica.`);
      });

      // 3. Upload de Foto Real via FileReader
      document.getElementById('input-proc-foto').addEventListener('change', (e) => {
        const file = e.target.files && e.target.files[0];
        if (!file) return;
        const reader = new FileReader();
        reader.onload = (ev) => {
          currentUploadBase64 = ev.target.result;
          const imgPrev = document.getElementById('img-upload-preview');
          imgPrev.src = currentUploadBase64;
          imgPrev.classList.remove('hidden');
          document.getElementById('foto-status-text').textContent = `Foto "${file.name}" carregada e pronta para ser anexada ao prontuário.`;
        };
        reader.readAsDataURL(file);
      });

      // Botão para gerar foto clínica de demonstração em 1 clique
      document.getElementById('btn-gerar-foto-demo').addEventListener('click', () => {
        const tipo = document.getElementById('select-proc-tipo').value;
        const cores = ['#0d9488', '#2563eb', '#7c3aed', '#db2777'];
        const cor = cores[Math.floor(Math.random() * cores.length)];
        currentUploadBase64 = gerarSvgClinicoBase64(tipo, 'Fotografia Clínica de Acompanhamento', cor);
        const imgPrev = document.getElementById('img-upload-preview');
        imgPrev.src = currentUploadBase64;
        imgPrev.classList.remove('hidden');
        document.getElementById('foto-status-text').textContent = 'Fotografia clínica de exemplo anexada ao formulário!';
        mostrarToast('Foto Selecionada', 'Imagem clínica pronta para o prontuário.', 'info');
      });

      // 2 & 3. Submissão de Procedimento + Foto + Agendamento de Retorno
      document.getElementById('form-procedimento').addEventListener('submit', (e) => {
        e.preventDefault();
        const clienteId = Number(document.getElementById('select-proc-cliente').value);
        const tipo = document.getElementById('select-proc-tipo').value;
        const dataProcedimento = document.getElementById('input-proc-data').value;
        const dataRetorno = document.getElementById('input-proc-retorno').value;
        const observacoes = document.getElementById('input-proc-obs').value.trim();

        if (!clienteId || !observacoes) return;

        const fotoFinal = currentUploadBase64 || gerarSvgClinicoBase64(tipo, `Paciente #${clienteId} • Registro Clínico`, '#0f766e');
        const novoProcId = db.procedimentos.length > 0 ? Math.max(...db.procedimentos.map(p => p.id)) + 1 : 101;

        db.procedimentos.unshift({
          id: novoProcId,
          clienteId,
          tipo,
          dataProcedimento,
          dataRetorno,
          observacoes,
          fotoBase64: fotoFinal,
          retornoConcluido: false
        });

        registrarSql(`INSERT INTO Procedimentos (Id, ClienteId, Tipo, DataProc, DataRetorno, FotoBase64, RetornoOk) VALUES (${novoProcId}, ${clienteId}, '${tipo}', '${dataProcedimento}', '${dataRetorno}', '[FOTO_CLINICA]', 0);`);
        currentUploadBase64 = '';
        document.getElementById('img-upload-preview').classList.add('hidden');
        document.getElementById('foto-status-text').textContent = 'Nenhuma foto selecionada (um cartão visual clínico será anexado automaticamente).';
        document.getElementById('input-proc-obs').value = '';

        renderizarTudo();
        mostrarToast('Atendimento Registrado', `Procedimento salvo no prontuário e retorno agendado para ${formatarDataBR(dataRetorno)}.`);
      });

      // 4. Filtros do Histórico e Abertura de Foto em Modal
      document.getElementById('filtro-historico-cliente').addEventListener('change', renderizarHistorico);
      document.getElementById('filtro-historico-busca').addEventListener('input', renderizarHistorico);

      document.getElementById('historico-grid').addEventListener('click', (e) => {
        const btn = e.target.closest('[data-open-photo]');
        if (!btn) return;
        const procId = Number(btn.getAttribute('data-open-photo'));
        const proc = db.procedimentos.find(p => p.id === procId);
        if (!proc) return;

        document.getElementById('modal-title').textContent = `${proc.tipo} — ${obterNomeCliente(proc.clienteId)}`;
        document.getElementById('modal-subtitle').textContent = `Atendimento #${proc.id} realizado em ${formatarDataBR(proc.dataProcedimento)} | Retorno: ${formatarDataBR(proc.dataRetorno)}`;
        document.getElementById('modal-image').src = proc.fotoBase64;
        document.getElementById('photo-modal').classList.remove('hidden');
      });

      const fecharModal = () => document.getElementById('photo-modal').classList.add('hidden');
      document.getElementById('btn-close-modal').addEventListener('click', fecharModal);
      document.getElementById('btn-close-modal-footer').addEventListener('click', fecharModal);

      // 5. Interações do Painel de Retornos
      document.querySelectorAll('.ret-filter-btn').forEach(btn => {
        btn.addEventListener('click', () => {
          currentRetornoFilter = btn.getAttribute('data-ret-filter');
          document.querySelectorAll('.ret-filter-btn').forEach(b => {
            const ativo = b.getAttribute('data-ret-filter') === currentRetornoFilter;
            b.className = ativo
              ? 'ret-filter-btn px-3 py-1.5 rounded-lg text-xs font-semibold bg-slate-900 text-white'
              : 'ret-filter-btn px-3 py-1.5 rounded-lg text-xs font-semibold bg-slate-100 text-slate-700 hover:bg-slate-200';
          });
          renderizarPainelRetornos();
        });
      });

      document.getElementById('tabela-retornos-body').addEventListener('click', (e) => {
        const btn = e.target.closest('[data-toggle-retorno]');
        if (!btn) return;
        const procId = Number(btn.getAttribute('data-toggle-retorno'));
        const proc = db.procedimentos.find(p => p.id === procId);
        if (!proc) return;

        proc.retornoConcluido = !proc.retornoConcluido;
        registrarSql(`UPDATE Procedimentos SET RetornoOk = ${proc.retornoConcluido ? 1 : 0} WHERE Id = ${proc.id};`);
        renderizarTudo();
        mostrarToast(
          'Status de Retorno Atualizado',
          `Retorno de ${obterNomeCliente(proc.clienteId)} marcado como ${proc.retornoConcluido ? 'Compareceu' : 'Pendente'}.`
        );
      });

      // 6. Validação de Persistência no Banco (Reload Simulado + Dump + Reset)
      document.getElementById('btn-simular-reload').addEventListener('click', () => {
        db = null;
        db = carregarBancoDoDisco();
        registrarSql('PRAGMA integrity_check; -- Dados recarregados do armazenamento persistente');
        renderizarTudo();

        const banner = document.getElementById('persistence-check-banner');
        const details = document.getElementById('persistence-check-details');
        details.textContent = `Foram recuperados ${db.clientes.length} pacientes e ${db.procedimentos.length} atendimentos (com fotos) diretamente do banco de dados às ${new Date().toLocaleTimeString('pt-BR')}.`;
        banner.classList.remove('hidden');
        mostrarToast('Persistência Confirmada', 'Todos os registros foram recarregados com sucesso a partir do banco de dados.');
      });

      document.getElementById('btn-exportar-json').addEventListener('click', () => {
        const dataStr = 'data:text/json;charset=utf-8,' + encodeURIComponent(JSON.stringify(db, null, 2));
        const a = document.createElement('a');
        a.setAttribute('href', dataStr);
        a.setAttribute('download', 'clinicafacil_backup.json');
        document.body.appendChild(a);
        a.click();
        a.remove();
        mostrarToast('Backup Concluído', 'Arquivo clinicafacil_backup.json exportado com sucesso.', 'info');
      });

      document.getElementById('btn-limpar-banco').addEventListener('click', () => {
        db = { clientes: [], procedimentos: [], sqlLogs: ['DELETE FROM Procedimentos; DELETE FROM Clientes; -- Registros limpos'] };
        salvarBancoNoDisco(db);
        renderizarTudo();
        mostrarToast('Registros Removidos', 'Os dados foram limpos. Clique em "Restaurar Pacientes de Demonstração" quando desejar.', 'alerta');
      });

      document.getElementById('btn-popular-demo').addEventListener('click', () => {
        db = criarDadosIniciais();
        registrarSql('-- Pacientes e prontuários de demonstração restaurados');
        salvarBancoNoDisco(db);
        renderizarTudo();
        mostrarToast('Dados Restaurados', 'Pacientes, procedimentos, fotos e retornos de exemplo carregados!');
      });

      // 7. Abas de Código C# + Google Colab
      document.querySelectorAll('.code-tab-btn').forEach(btn => {
        btn.addEventListener('click', () => {
          currentCodeTab = btn.getAttribute('data-code-tab');
          document.querySelectorAll('.code-tab-btn').forEach(b => {
            const ativo = b.getAttribute('data-code-tab') === currentCodeTab;
            b.className = ativo
              ? 'code-tab-btn px-3.5 py-2 rounded-xl text-xs font-bold bg-teal-600 text-white transition'
              : 'code-tab-btn px-3.5 py-2 rounded-xl text-xs font-bold bg-slate-100 text-slate-700 hover:bg-slate-200 transition';
          });
          renderizarCodigo();
        });
      });

      document.getElementById('btn-copiar-codigo').addEventListener('click', () => {
        const texto = CODE_SNIPPETS[currentCodeTab];
        const textarea = document.createElement('textarea');
        textarea.value = texto;
        document.body.appendChild(textarea);
        textarea.select();
        try {
          document.execCommand('copy');
          const lbl = document.getElementById('copy-btn-label');
          lbl.textContent = '✓ Código Copiado!';
          setTimeout(() => { lbl.textContent = 'Copiar Aba Selecionada'; }, 2000);
          mostrarToast('Código Copiado', 'Trecho copiado para a área de transferência.', 'info');
        } catch (err) {
          console.warn(err);
        }
        textarea.remove();
      });

      // Render inicial
      renderizarTudo();
      renderizarCodigo();
    });
